/* @autogenerated */
import { environment } from 'app/bootstrap/environment/environment';
import { signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { HttpClientTestingModule, HttpTestingController } from '@angular/common/http/testing';
import { provideTransloco, TRANSLOCO_CONFIG, TRANSLOCO_MISSING_HANDLER, TranslocoService } from '@jsverse/transloco';
import { Subject } from 'rxjs';
import { rootLogger } from '@shared/context/observability/logger.service';
import { I18nLoaderService, provideI18nConfiguration, versionQuery } from './i18n-loader.service';
import { APP_CONFIG, AppConfig, RuntimeConfigService } from './app-config.service';
import { I18nConfig } from './app-config.model';
import { HumanizingMissingHandler } from './missing-handler';
import { MFE_REMOTES_GLOBAL } from './mfe-config.adapter';

const runtimeConfig = (i18n: I18nConfig) => ({ provide: APP_CONFIG, useValue: signal({ i18n } as AppConfig) });
const testConfig = runtimeConfig({ 'default-lang': 'en', 'available-langs': ['en', 'es'] });

describe('I18nLoaderService', () => {
  let service: I18nLoaderService;
  let http: HttpTestingController;

  beforeEach(() => {
    TestBed.configureTestingModule({
      imports: [HttpClientTestingModule],
      providers: [testConfig],
    });
    service = TestBed.inject(I18nLoaderService);
    http = TestBed.inject(HttpTestingController);
  });

  afterEach(() => {
    http.verify();
    TestBed.resetTestingModule();
  });

  it('fetches a single file for the default language', (done) => {
    service.getTranslation('en').subscribe((result) => {
      expect(result).toEqual({ title: 'Hello' });
      done();
    });

    http.expectOne('i18n/en.json').flush({ title: 'Hello' });
  });

  it('fetches fallback chain for a regional lang (es uses en as fallback)', (done) => {
    service.getTranslation('es').subscribe((result) => {
      expect(result['farewell']).toBe('adios');
      expect(result['greeting']).toBe('hello');
      done();
    });

    http.expectOne('i18n/es.json').flush({ farewell: 'adios' });
    http.expectOne('i18n/en.json').flush({ greeting: 'hello' });
  });

  it('fetches scoped translations under the correct path', (done) => {
    service.getTranslation('myFeature/en').subscribe((result) => {
      expect(result).toEqual({ scoped: true });
      done();
    });

    http.expectOne('i18n/myFeature/en.json').flush({ scoped: true });
  });

  it('merges translations deeply across fallback chain', (done) => {
    service.getTranslation('es').subscribe((result) => {
      expect(result).toEqual({
        common: { save: 'save', cancel: 'cancel' },
        extra: { only: 'es' },
      });
      done();
    });

    http.expectOne('i18n/es.json').flush({ extra: { only: 'es' } });
    http.expectOne('i18n/en.json').flush({ common: { save: 'save', cancel: 'cancel' } });
  });

  it('recursively deep-merges nested objects shared between fallbacks', (done) => {
    // Both es and en have the same top-level 'ui' key with objects as values.
    // deepMerge must recurse into 'ui' (the IF branch where both target[key] and source[key] are objects).
    service.getTranslation('es').subscribe((result) => {
      expect(result).toEqual({
        ui: { btn: { cancel: 'cancelar', save: 'save' } },
      });
      done();
    });

    http.expectOne('i18n/es.json').flush({ ui: { btn: { cancel: 'cancelar' } } });
    http.expectOne('i18n/en.json').flush({ ui: { btn: { save: 'save' } } });
  });

  it('overrides arrays (does not deep-merge them)', (done) => {
    service.getTranslation('es').subscribe((result) => {
      expect(result['items']).toEqual(['uno', 'dos']);
      done();
    });

    http.expectOne('i18n/es.json').flush({ items: ['uno', 'dos'] });
    http.expectOne('i18n/en.json').flush({ items: ['one', 'two', 'three'] });
  });

  it('gives the requested language priority over the default one on the same key', (done) => {
    service.getTranslation('es').subscribe((result) => {
      expect(result).toEqual({ ui: { save: 'guardar', cancel: 'cancel' }, title: 'Título' });
      done();
    });

    http.expectOne('i18n/es.json').flush({ ui: { save: 'guardar' }, title: 'Título' });
    http.expectOne('i18n/en.json').flush({ ui: { save: 'save', cancel: 'cancel' }, title: 'Title' });
  });

  it('loads a scope that only has es.json when lang is es', (done) => {
    const warn = spyOn(rootLogger, 'warn');
    service.getTranslation('identity/tenant/es').subscribe((result) => {
      expect(result).toEqual({ list: { title: 'Inquilinos' } });
      expect(warn).toHaveBeenCalledTimes(1);
      done();
    });

    http.expectOne('i18n/identity/tenant/es.json').flush({ list: { title: 'Inquilinos' } });
    http.expectOne('i18n/identity/tenant/en.json').flush('Not found', { status: 404, statusText: 'Not Found' });
  });

  it('returns an empty translation when every file is missing, warning once per file', (done) => {
    const warn = spyOn(rootLogger, 'warn');
    service.getTranslation('missing/en').subscribe((first) => {
      expect(first).toEqual({});
      service.getTranslation('missing/en').subscribe((second) => {
        expect(second).toEqual({});
        expect(warn).toHaveBeenCalledTimes(1);
        done();
      });
      http.expectOne('i18n/missing/en.json').flush('', { status: 404, statusText: 'Not Found' });
    });

    http.expectOne('i18n/missing/en.json').flush('', { status: 404, statusText: 'Not Found' });
  });

  it('uses remote base URL when the host registered a remote', (done) => {
    (window as any)[MFE_REMOTES_GLOBAL] = { [environment.name]: ['https://cdn.example.com/', 'config.json'] };

    service.getTranslation('en').subscribe((result) => {
      expect(result).toEqual({ remote: true });
      delete (window as any)[MFE_REMOTES_GLOBAL];
      done();
    });

    http.expectOne('https://cdn.example.com/i18n/en.json').flush({ remote: true });
  });
});

describe('I18nLoaderService — unknown lang', () => {
  let service: I18nLoaderService;
  let http: HttpTestingController;
  let setAvailableLangsSpy: jasmine.Spy;

  beforeEach(() => {
    setAvailableLangsSpy = jasmine.createSpy('setAvailableLangs');
    TestBed.configureTestingModule({
      imports: [HttpClientTestingModule],
      providers: [testConfig, { provide: TranslocoService, useValue: { setAvailableLangs: setAvailableLangsSpy } }],
    });
    service = TestBed.inject(I18nLoaderService);
    http = TestBed.inject(HttpTestingController);
  });

  afterEach(() => {
    http.verify();
    TestBed.resetTestingModule();
  });

  it('calls setAvailableLangs when lang is not in config', (done) => {
    service.getTranslation('fr').subscribe(() => {
      expect(setAvailableLangsSpy).toHaveBeenCalledWith(['en', 'es', 'fr']);
      done();
    });

    // 'fr' not in availableLangs → langsPath falls back to only defaultLang 'en'
    http.expectOne('i18n/en.json').flush({});
  });

  it('uses the base language file for a regional variant that is not available', (done) => {
    service.getTranslation('es-AR').subscribe((result) => {
      expect(result['title']).toBe('Título');
      done();
    });

    http.expectOne('i18n/es.json').flush({ title: 'Título' });
    http.expectOne('i18n/en.json').flush({ title: 'Title' });
  });

  it('uses || "" fallback when pop() returns empty string (path is "")', (done) => {
    // ''.split('/') → [''] → pop() → '' (falsy) → lang = '' via || ''
    // langsPath('', config): ''.split('/').pop() → '' (falsy) → lang = '' via || ''
    // '' not in availableLangs → setAvailableLangs called, only defaultLang 'en' fetched
    service.getTranslation('').subscribe((result) => {
      expect(setAvailableLangsSpy).toHaveBeenCalledWith(['en', 'es', '']);
      expect(result).toEqual({});
      done();
    });

    http.expectOne('i18n/en.json').flush({});
  });
});

describe('I18nLoaderService — 3-step fallback chain', () => {
  let service: I18nLoaderService;
  let http: HttpTestingController;

  beforeEach(() => {
    TestBed.configureTestingModule({
      imports: [HttpClientTestingModule],
      providers: [runtimeConfig({ 'default-lang': 'en', 'available-langs': ['en', 'es', 'es-ES'] })],
    });
    service = TestBed.inject(I18nLoaderService);
    http = TestBed.inject(HttpTestingController);
  });

  afterEach(() => {
    http.verify();
    TestBed.resetTestingModule();
  });

  it('fetches es-ES, es and en for a regional variant', (done) => {
    service.getTranslation('es-ES').subscribe((result) => {
      expect(result['a']).toBe('a-es-ES');
      expect(result['b']).toBe('b-es');
      expect(result['c']).toBe('c-en');
      // En una clave repetida gana el más específico
      expect(result['shared']).toBe('es-ES');
      done();
    });

    http.expectOne('i18n/es-ES.json').flush({ a: 'a-es-ES', shared: 'es-ES' });
    http.expectOne('i18n/es.json').flush({ b: 'b-es', shared: 'es' });
    http.expectOne('i18n/en.json').flush({ c: 'c-en', shared: 'en' });
  });
});

describe('provideI18nConfiguration', () => {
  // Como en app.config.ts: provideI18nConfiguration() sustituye la configuración y el missing handler de provideTransloco()
  const i18nProviders = () => [provideTransloco({ config: {} }), ...provideI18nConfiguration()];

  afterEach(() => TestBed.resetTestingModule());

  it('builds the config with defaults when the runtime config has not arrived yet', () => {
    // Otro APP_INITIALIZER puede crear TranslocoService antes de que llegue la configuración
    TestBed.configureTestingModule({ providers: [...i18nProviders()] });

    const config = TestBed.inject(TRANSLOCO_CONFIG);
    expect(config.defaultLang).toBe('en');
    expect(config.availableLangs as string[]).toEqual(['en']);
  });

  it('updates Transloco languages when the runtime config arrives', () => {
    const config$ = new Subject<AppConfig>();
    TestBed.configureTestingModule({
      providers: [{ provide: RuntimeConfigService, useValue: { config$: config$.asObservable() } }, ...i18nProviders()],
    });
    const transloco = TestBed.inject(TranslocoService);
    expect(transloco.getDefaultLang()).toBe('en');

    config$.next({ i18n: { 'default-lang': 'es', 'available-langs': ['es', 'en'] } } as AppConfig);

    expect(transloco.getDefaultLang()).toBe('es');
    expect(transloco.getAvailableLangs() as string[]).toEqual(['es', 'en']);
  });

  it('provides TRANSLOCO_CONFIG with defaultLang from runtime conf', () => {
    TestBed.configureTestingModule({
      providers: [runtimeConfig({ 'default-lang': 'fr', 'available-langs': ['fr', 'en'] }), ...i18nProviders()],
    });

    const config = TestBed.inject(TRANSLOCO_CONFIG);
    expect(config.defaultLang).toBe('fr');
  });

  it('provides TRANSLOCO_CONFIG with available languages', () => {
    TestBed.configureTestingModule({
      providers: [runtimeConfig({ 'default-lang': 'en', 'available-langs': ['en', 'es', 'de'] }), ...i18nProviders()],
    });

    const config = TestBed.inject(TRANSLOCO_CONFIG);
    expect(config.availableLangs).toContain('de');
  });

  it('adds defaultLang to availableLangs when not present', () => {
    TestBed.configureTestingModule({
      providers: [runtimeConfig({ 'default-lang': 'pt', 'available-langs': ['en', 'es'] }), ...i18nProviders()],
    });

    const config = TestBed.inject(TRANSLOCO_CONFIG);
    expect(config.availableLangs as string[]).toContain('pt');
  });

  it('falls back to en as the only language when i18n conf is empty', () => {
    TestBed.configureTestingModule({
      providers: [runtimeConfig({}), ...i18nProviders()],
    });

    const config = TestBed.inject(TRANSLOCO_CONFIG);
    expect(config.defaultLang).toBe('en');
    expect(config.availableLangs as string[]).toEqual(['en']);
  });
});

describe('versionQuery', () => {
  it('is empty outside a build (ng serve, tests)', () => {
    expect(environment.buildDate).toBeUndefined();
    expect(environment.version).toBe('dev');
    expect(versionQuery()).toBe('');
  });

  it('adds the encoded build version so a deploy does not serve cached translations', () => {
    const query = versionQuery({ name: 'phylax', version: '1.2.0+abc', buildDate: '2026-11-01T00:00:00.000Z' });
    expect(query).toBe('?v=1.2.0%2Babc');
  });
});
